import { z } from "zod";
export const GetLicenseRequirementsSchema = z.object({ tier: z.enum(["learner", "general", "specialized", "operator"]).describe("License tier to inspect"), jurisdiction: z.string().min(1).describe("Jurisdiction code, e.g. GLOBAL"), endorsementType: z.string().optional().describe("Optional specialized endorsement domain") });
export const ApplyLearnerSchema = z.object({ applicantId: z.string().min(1).describe("Unique applicant human ID"), age: z.number().int().min(0).describe("Applicant age in years"), jurisdiction: z.string().min(1).describe("Jurisdiction code"), guardianConsent: z.boolean().optional().describe("Required in some jurisdictions for younger applicants"), educationModuleSet: z.array(z.string()).min(1).describe("Completed training modules such as VOW-101"), requestedAccessScope: z.string().min(1).describe("Requested access scope description") });
export const IssueLicenseSchema = z.object({ humanId: z.string().min(1), jurisdiction: z.string().min(1), tier: z.enum(["learner", "general", "specialized", "operator"]), endorsements: z.array(z.string()).optional(), restrictions: z.array(z.string()).optional() });
